import{_ as n,l as o,o as a,c as s,v as t,p as l,x as r,d as u,i as m,S as c}from"./chunks/framework.InCnrqk-.js";const A=JSON.parse('{"title":"vruntime","description":"","frontmatter":{"title":"vruntime","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/cfs-vruntime.md","filePath":"cs/cfs-vruntime.md","lastUpdated":1789023840000}'),d={name:"cs/cfs-vruntime.md"};function p(h,e,_,v,E,f){const i=o("Mermaid");return a(),s("div",null,[e[1]||(e[1]=t('<h1 id="vruntime" tabindex="-1">vruntime <a class="header-anchor" href="#vruntime" aria-label="Permalink to &quot;vruntime&quot;">​</a></h1><div class="epigraph"><p>虚拟运行时间把「已经吃到的 CPU」按权重折算到同一把尺子上；调度器总是把尺子最小的那个请上 CPU。</p><footer>—— 据 Linux CFS 设计直觉；Silberschatz et al. 对公平份额的整理</footer></div><p><a href="/cs/timeslice-cfs">上一课</a>已经用权重摊时间和虚拟时钟给过直觉：实际跑 \\(\\Delta t\\)，<code>vruntime</code> 增加约 \\(\\Delta t \\cdot w_0/w_i\\)。缺口是把这根尺子<strong>钉成可执行的记账</strong>：何时加、睡眠醒来如何安放、为何用一棵有序树而不是扫描全表。本课仍是直觉，不是内核字段转写。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>只有「选吃得最少的」这句话，还没有说明：新任务第一次入队时 vruntime 从哪来；睡了很久的任务若保留旧值，会不会醒来独占。缺口不是再解释权重公平的目标，而是 <strong>vruntime 的时间线</strong>：每个可运行任务一个标量，runqueue 上总有一个最小值（常叫 min_vruntime）作为原点，避免数无限涨、避免睡眠者带着远古亏欠冲进来。</p><p><span class="marginnote">权重只出现在增量里。比较时只比较 vruntime，不再当场做除法。树的最左结点即下一个。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>任务在 CPU 上每过一段实际时间，给它的 vruntime 加上折算增量。入队：取 max(自己的 vruntime, 当前队列最小附近)，以免睡眠补偿变成无限赊账。出队睡眠：冻结其 vruntime。选下一个：最小 vruntime。时间片长度可以随可运行个数变化，使延迟目标大致恒定——这是实现旋钮，定义仍是「追平虚拟时间」。</p>',8)),(a(),l(c,null,{default:r(()=>[m(i,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20RUN%5B%22%E5%AE%9E%E9%99%85%E8%B7%91%20%CE%94t%22%5D%20--%3E%20ADD%5B%22vruntime%20%2B%3D%20%E6%8A%98%E7%AE%97%22%5D%0A%20%20ADD%20--%3E%20TREE%5B%22%E6%9C%89%E5%BA%8F%E6%A0%91%E6%8C%89%20vruntime%22%5D%0A%20%20TREE%20--%3E%20PICK%5B%22%E6%9C%80%E5%B0%8F%E8%80%85%E4%B8%8A%20CPU%22%5D%0A"})]),fallback:r(()=>[...e[0]||(e[0]=[u(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=t('<p>与<a href="/cs/runqueue">运行队列</a>的关系：CFS 的队列不是 FIFO，是按 vruntime 排序的集合。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>vruntime 把 RR 的「人次」换成「份额」。I/O 型少占实际时间，虚拟时钟走得慢（若权重相同则增量小），醒来后仍靠近最小端，于是很快再被选中——这解释了交互性，而不靠 MLFQ 降档。与<a href="/cs/priority-inversion">优先级反转</a>不同，这里没有固定优先级可继承；锁争用仍能让「vruntime 最小者」跑不成，那是锁课。</p><p>溢出与衰减是实现；主干只要求比较在同一原点上进行。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不保证与某主线版本的 <code>vruntime</code> 位宽、EEVDF 的合格时延公式一致。实时 FIFO 任务不走这根尺子。也不把红黑树旋转当调度理论。</p><p>后课默认：比较用 vruntime。用户怎么改那份权重，下一课讲 nice。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>vruntime 是按权重折算的已跑时间；选最小者。</li><li>醒来安放到当前最小附近，避免无限亏欠。</li><li>nice 如何改权重是下一课。</li><li>出处：Linux CFS 设计讨论；Silberschatz et al., <em>OSC</em>。</li></ul>',9))])}const P=n(d,[["render",p]]);export{A as __pageData,P as default};
